long toSeconds(def raw) { if (raw == null) { return -1L; } String s = raw.toString().trim(); if (s.length() < 2) { return -1L; } String unit = s.substring(s.length() - 1); String num = s.substring(0, s.length() - 1); for (int i = 0; i < num.length(); i++) { if (!Character.isDigit(num.charAt(i))) { return -1L; } } long n = Long.parseLong(num); if (unit == 's') { return n; } if (unit == 'm') { return n * 60L; } if (unit == 'h') { return n * 3600L; } if (unit == 'd') { return n * 86400L; } return -1L; }

if (ctx.lagprof == null || ctx.lagprof.rule == null) { throw new IllegalArgumentException('missing lagprof.rule'); }
Map r = ctx.lagprof.rule;

// Workflow templates render missing values as empty strings or 'null'. Treat those as missing.
for (String k : ['type', 'interval_raw', 'from_raw', 'index_patterns', 'data_view_id', 'timestamp_override', 'timestamp_override_fallback_disabled']) {
  def v = r.get(k);
  if (v instanceof String) { String t = ((String) v).trim(); if (t == '' || t == 'null' || t == 'undefined' || t == 'None' || t == '[]') { r.remove(k); } }
}

// Index patterns may arrive as a list, or as a string such as 'a,b' or '["a","b"]'.
List pats = new ArrayList();
def rawPats = r.get('index_patterns');
if (rawPats instanceof List) { for (def p : rawPats) { if (p != null) { pats.add(p.toString().trim()); } } }
else if (rawPats != null) { String t = rawPats.toString().replace('[', '').replace(']', '').replace('"', ''); for (String p : t.splitOnToken(',')) { pats.add(p.trim()); } }
List local = new ArrayList();
boolean remoteSkipped = false;
for (String p : pats) { if (p == '') { continue; } if (p.contains(':')) { remoteSkipped = true; } else { local.add(p); } }
r.index_patterns = pats;
r.index_patterns_csv = String.join(',', local);
r.remote_patterns_skipped = remoteSkipped;

def fb = r.get('timestamp_override_fallback_disabled');
if (fb instanceof String) { r.timestamp_override_fallback_disabled = ((String) fb).trim().equalsIgnoreCase('true'); }

long interval = toSeconds(r.get('interval_raw'));
long lookback = -1L;
def from = r.get('from_raw');
if (from != null && from.toString().trim().startsWith('now-')) { lookback = toSeconds(from.toString().trim().substring(4)); }
if (interval > 0) { r.interval_s = interval; }
if (lookback > 0) { r.lookback_s = lookback; }

r.timestamp_field = r.get('timestamp_override') != null ? r.get('timestamp_override').toString() : '@timestamp';

String reason = null;
def type = r.get('type');
if (type == 'machine_learning') { reason = 'machine learning rule'; }
else if (type == 'esql') { reason = 'ES|QL rule'; }
else if (local.isEmpty()) {
  if (r.get('data_view_id') != null) { reason = 'uses a data view (not resolved in this version)'; }
  else if (remoteSkipped) { reason = 'only remote cluster index patterns'; }
  else { reason = 'no index patterns'; }
}
else if (interval <= 0) { reason = 'interval could not be parsed'; }
else if (lookback <= 0) { reason = 'from could not be parsed'; }

r.supported = reason == null;
if (reason != null) { r.unsupported_reason = reason; } else { r.remove('unsupported_reason'); }
